// Physician Assistant - Medical Case Challenge Practice Test 4. Original questions written for Valus from the
// HOSA 2026–27 test plan, slightly harder than the sample items: short clinical cases across body systems,
// assessment and diagnostic reasoning not covered in Practice Tests 1–3.
import {q, mix} from './q.js';
const CMDT='Papadakis et al., Current Medical Diagnosis & Treatment', MP='MedlinePlus';
const DP='Disease Process & Terminology (includes cancer & neoplasms)', INTEG='Integumentary', MSK='Musculoskeletal', CIRC='Circulatory & Lymphatic', RESP='Respiratory', DIG='Digestive', ENDO='Endocrine', NERV='Nervous & Senses', REPRO='Reproductive', URIN='Urinary', MENT='Mental Disorders', ASSESS='Patient Assessment', DX='Diagnosis';

export default {
 id:'physician-assistant-4',
 event:'Physician Assistant - Medical Case Challenge',
 title:'Practice Test 4',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Current Medical Diagnosis & Treatment (CMDT) and MedlinePlus',
 plan:[{area:DP,weight:10},{area:INTEG,weight:4},{area:MSK,weight:6},{area:CIRC,weight:10},{area:RESP,weight:6},{area:DIG,weight:10},{area:ENDO,weight:6},{area:NERV,weight:8},{area:REPRO,weight:4},{area:URIN,weight:4},{area:MENT,weight:6},{area:ASSESS,weight:12},{area:DX,weight:14}],
 questions:mix([
  q(DP,'What does the incidence of a disease measure?','New cases in a population over a period of time',['All existing cases at one point in time','Deaths from the disease in a single year','The share of patients who recover fully'],'A','Incidence counts new cases over time; prevalence counts all existing cases, new and old, at a point or period in time.',CMDT),
  q(DP,'A patient with advanced cancer receives treatment aimed at relieving pain and improving comfort, not cure. What is this called?','Palliative care',['Curative therapy','Adjuvant therapy','Preventive care'],'B','Palliative care focuses on relieving symptoms and improving quality of life at any stage of serious illness, alongside or after other treatment.',CMDT),
  q(DP,'A biopsy report reads “carcinoma in situ.” What does this mean?','Cancer cells have not invaded past the basement membrane',['Cancer has spread to nearby lymph nodes in the region','The tumor is benign and will not change over time','Cancer has spread to distant organs through the blood'],'C','Carcinoma in situ is a malignant change confined to the epithelium; it has not invaded the basement membrane, so it cannot yet metastasize.',CMDT),
  q(DP,'Before a migraine or an infection’s full symptoms appear, a patient feels early warning signs such as fatigue. What is this stage called?','The prodrome',['The remission','The sequela','The relapse'],'D','A prodrome is the early set of nonspecific symptoms before a disease’s characteristic signs appear; a sequela is a lasting aftereffect.',CMDT),
  q(DP,'A woman’s mother and sister had breast and ovarian cancer at young ages. Which inherited gene change is most associated with this pattern?','BRCA1 or BRCA2 mutation',['HER2 gene amplification','Philadelphia chromosome','APC gene mutation'],'A','Inherited BRCA1 and BRCA2 mutations greatly raise the risk of breast and ovarian cancer; genetic counseling and testing are recommended.',CMDT),
  q(INTEG,'A patient has an itchy, ring-shaped red patch with a scaly border and central clearing. A KOH prep shows hyphae. What is the diagnosis?','Tinea corporis',['Nummular eczema','Pityriasis rosea','Granuloma annulare'],'B','Tinea corporis (ringworm) is a fungal infection with an annular scaly border; KOH microscopy showing branching hyphae confirms it.',CMDT),
  q(INTEG,'Several family members have intense itching that is worse at night, with tiny burrows between the fingers. What is the most likely diagnosis?','Scabies',['Contact dermatitis','Head lice','Hives'],'C','Scabies mites burrow into the skin, especially finger webs and wrists, causing severe nighttime itching that spreads by close contact.',CMDT),
  q(MSK,'After a fall on an outstretched hand, a patient has tenderness in the anatomical snuffbox, but the first X-ray is normal. Which injury must be suspected?','Scaphoid fracture',['Colles fracture','Boxer’s fracture','Elbow dislocation'],'D','Scaphoid fractures often do not show on early X-rays; snuffbox tenderness calls for a splint and repeat imaging because the bone can lose its blood supply.',CMDT),
  q(MSK,'After a crush injury, a patient’s leg pain is far worse than expected and increases sharply when the toes are passively stretched. What is the concern?','Compartment syndrome',['A simple muscle strain','Deep vein thrombosis','Achilles tendinitis'],'A','Compartment syndrome raises pressure within a muscle compartment; pain out of proportion and pain on passive stretch are early signs needing urgent fasciotomy.',CMDT),
  q(MSK,'A painter has shoulder pain when lifting the arm between 60 and 120 degrees and cannot hold the arm out once it is lowered. What is the likely injury?','Rotator cuff tear',['Adhesive capsulitis','Clavicle fracture','Biceps rupture'],'B','A painful arc and a positive drop-arm test suggest a rotator cuff tear, most often of the supraspinatus tendon.',CMDT),
  q(CIRC,'A 70-year-old male smoker has a pulsating mass in the abdomen just above the navel. What is the most likely diagnosis?','Abdominal aortic aneurysm',['Incarcerated umbilical hernia','Pancreatic pseudocyst','Enlarged spleen'],'C','An AAA presents as a pulsatile midline abdominal mass; older male smokers are at highest risk, and ultrasound is used to screen and measure it.',CMDT),
  q(CIRC,'An ECG shows a PR interval of 0.24 seconds, and every P wave is followed by a QRS. What is the rhythm?','First-degree AV block',['Second-degree AV block','Third-degree heart block','Atrial flutter'],'D','First-degree AV block is a fixed PR interval longer than 0.20 seconds with every beat conducted; it is usually benign.',CMDT),
  q(CIRC,'Which group of findings best fits right-sided heart failure?','Jugular venous distention, leg edema and an enlarged liver',['Crackles in the lungs, orthopnea and pink frothy sputum','A barrel chest, wheezing and pursed-lip breathing','Fever, a new murmur and splinter hemorrhages'],'A','Right-sided failure backs blood up into the systemic veins, causing JVD, peripheral edema and hepatomegaly; left-sided failure causes lung congestion.',CMDT),
  q(CIRC,'A young adult with sickle cell disease has severe pain in the back and limbs after dehydration. What is happening?','A vaso-occlusive pain crisis',['An allergic drug reaction','A muscle strain from exercise','An acute arterial embolism'],'B','Dehydration and stress can cause sickled cells to block small vessels, leading to tissue ischemia and severe pain; fluids and pain control are key.',CMDT),
  q(CIRC,'After breast cancer surgery with removal of axillary lymph nodes, a patient develops chronic swelling of the arm. What is this called?','Lymphedema',['Cellulitis','Phlebitis','Raynaud phenomenon'],'C','Removing or damaging lymph nodes impairs lymph drainage, causing protein-rich fluid to collect in the limb as lymphedema.',CMDT),
  q(RESP,'Pulmonary function tests show a reduced total lung capacity and FVC with a normal or high FEV1/FVC ratio. What pattern is this?','A restrictive lung disease pattern',['An obstructive lung disease pattern','A completely normal lung pattern','An upper airway obstruction only'],'D','Restrictive diseases such as pulmonary fibrosis reduce lung volumes; the FEV1/FVC ratio stays normal or rises, unlike in obstructive disease.',CMDT),
  q(RESP,'An unvaccinated child has bouts of rapid coughing ending in a high-pitched “whoop” and vomiting after coughing. What is the diagnosis?','Pertussis',['Croup','Asthma','Bronchiolitis'],'A','Pertussis (whooping cough) from Bordetella pertussis causes paroxysms of cough with an inspiratory whoop; vaccination prevents it.',CMDT),
  q(RESP,'A child has high fever, drooling, muffled voice and sits leaning forward. A lateral neck X-ray shows a thumbprint sign. What is the diagnosis?','Epiglottitis',['Croup','Peritonsillar abscess','Foreign body in the airway'],'B','Epiglottitis is a swollen epiglottis that can block the airway; the child should be kept calm and the airway secured by an expert.',CMDT),
  q(DIG,'Several people who ate at the same restaurant develop fever, nausea and jaundice weeks later. Which virus is most likely?','Hepatitis A',['Hepatitis B','Hepatitis C','Hepatitis D'],'C','Hepatitis A spreads by the fecal–oral route through contaminated food or water and causes acute illness without chronic infection.',CMDT),
  q(DIG,'A patient has burning chest pain after meals that is worse when lying down and improves with antacids. What is the most likely diagnosis?','Gastroesophageal reflux disease',['Acute myocardial infarction','Esophageal cancer with obstruction','Acute cholecystitis'],'D','GERD occurs when stomach acid flows back into the esophagus; heartburn after meals and on lying down is typical, and PPIs are first-line therapy.',CMDT),
  q(DIG,'A patient has trouble swallowing both solids and liquids, and a barium swallow shows a “bird’s beak” narrowing. What is the diagnosis?','Achalasia',['Esophageal web','Esophageal candidiasis','Hiatal hernia'],'A','In achalasia, the lower esophageal sphincter fails to relax, causing dysphagia to solids and liquids and a bird’s-beak shape on barium study.',CMDT),
  q(DIG,'A 1-year-old has episodes of severe crying with knees drawn up, and stools that look like currant jelly. What is the diagnosis?','Intussusception',['Pyloric stenosis','Meckel diverticulum','Celiac disease'],'B','Intussusception is the telescoping of bowel into itself; ultrasound shows a target sign, and an air or contrast enema can diagnose and reduce it.',MP),
  q(DIG,'After an episode of heavy drinking and forceful vomiting, a patient vomits bright red blood. What is the most likely cause?','A Mallory–Weiss tear',['Esophageal varices','Gastric adenocarcinoma','Boerhaave syndrome'],'C','A Mallory–Weiss tear is a mucosal tear at the gastroesophageal junction from retching; bleeding usually stops on its own.',CMDT),
  q(ENDO,'An older adult with type 2 diabetes has glucose over 900 mg/dL, severe dehydration and confusion, with little or no ketones. What is the diagnosis?','Hyperosmolar hyperglycemic state',['Diabetic ketoacidosis','Hypoglycemic coma','Nephrogenic diabetes insipidus'],'D','HHS causes extreme hyperglycemia and dehydration with high serum osmolality but little ketosis, because some insulin is still present.',CMDT),
  q(ENDO,'After a head injury, a patient produces large amounts of very dilute urine and is constantly thirsty. Blood glucose is normal. What is the likely cause?','Central diabetes insipidus',['Type 1 diabetes mellitus','SIADH from the head injury','Primary hyperaldosteronism'],'A','Central diabetes insipidus is a lack of ADH, so the kidneys cannot concentrate urine; glucose is normal, unlike diabetes mellitus.',CMDT),
  q(ENDO,'A woman has missed periods and milky nipple discharge while not pregnant. An MRI shows a small pituitary mass. What is the most likely diagnosis?','Prolactinoma',['Acromegaly','Cushing disease','Sheehan syndrome'],'B','A prolactinoma secretes prolactin, causing galactorrhea and suppressing ovulation; it is the most common functioning pituitary tumor.',CMDT),
  q(NERV,'A patient has sudden slurred speech and arm weakness that fully resolve within 30 minutes. Imaging shows no infarct. What is the diagnosis?','Transient ischemic attack',['Completed ischemic stroke','Hemorrhagic stroke','Complex migraine only'],'C','A TIA causes temporary neurologic symptoms without infarction and signals a high short-term risk of stroke, so urgent workup is needed.',CMDT),
  q(NERV,'A man has attacks of severe pain around one eye, with tearing and a runny nostril on the same side, every night for weeks. What is the diagnosis?','Cluster headache',['Tension-type headache','Migraine without aura','Sinusitis headache'],'D','Cluster headaches are short, intense, one-sided orbital headaches with autonomic signs, occurring in clusters and more common in men.',CMDT),
  q(NERV,'On the Rinne test, bone conduction is louder than air conduction in the right ear. What type of hearing loss does this suggest?','Conductive hearing loss in the right ear',['Sensorineural hearing loss in the right ear','Normal hearing in both of the ears','Sensorineural hearing loss in the left ear'],'A','Normally air conduction is louder than bone conduction; when bone conduction is louder, sound is blocked in the outer or middle ear.',CMDT),
  q(NERV,'A nearsighted patient sees sudden flashes, many new floaters and a dark curtain over part of their vision. What is the emergency?','Retinal detachment',['Macular degeneration','Acute conjunctivitis','Cataract progression'],'B','Flashes, floaters and a curtain-like shadow suggest the retina is separating from the back of the eye; urgent repair can save vision.',CMDT),
  q(REPRO,'At 32 weeks of pregnancy, a patient has blood pressure of 158/104, protein in the urine and a headache. What is the most likely diagnosis?','Preeclampsia with severe features',['Chronic hypertension without other findings','Gestational diabetes','Placental abruption'],'C','Preeclampsia is new hypertension after 20 weeks with proteinuria or organ involvement; a pressure of 160/110 or symptoms like headache mark severe features.',CMDT),
  q(REPRO,'A sexually active young woman has lower abdominal pain, fever and cervical motion tenderness. What is the most likely diagnosis?','Pelvic inflammatory disease',['Ovarian cyst rupture','Urinary tract infection','Normal ovulation pain'],'D','PID is an ascending infection, often from chlamydia or gonorrhea; cervical motion tenderness is a key exam finding.',CMDT),
  q(URIN,'Which finding defines chronic kidney disease?','Reduced GFR or kidney damage lasting more than 3 months',['One elevated creatinine during a short illness','Any urinary tract infection within the last year','Dark urine after hard exercise on a single day'],'A','CKD is defined by a GFR below 60 mL/min/1.73 m² or markers of kidney damage, such as albuminuria, present for more than 3 months.',CMDT),
  q(URIN,'A patient with a family history of kidney failure has flank pain, blood in the urine, hypertension and large kidneys full of cysts on both sides. What is the diagnosis?','Polycystic kidney disease',['Bilateral kidney stones','Renal cell carcinoma','Acute pyelonephritis'],'B','Autosomal dominant polycystic kidney disease causes many cysts that enlarge both kidneys, leading to hypertension, hematuria and kidney failure.',CMDT),
  q(MENT,'A patient spends hours a day washing their hands because of intrusive fears of germs, and knows the fears are excessive. What is the diagnosis?','Obsessive-compulsive disorder',['Generalized anxiety disorder','Illness anxiety disorder','Specific phobia'],'C','OCD involves obsessions (intrusive unwanted thoughts) and compulsions (repetitive acts to reduce anxiety) that take a lot of time or cause distress.',CMDT),
  q(MENT,'For a diagnosis of ADHD, which requirement must be met?','Several symptoms began before age 12 and occur in two or more settings',['Symptoms began after age 18 and occur only at home','Symptoms appear only during one stressful week of exams','Symptoms occur only at school and nowhere else in daily life'],'D','DSM criteria require several inattentive or hyperactive symptoms before age 12, present in two or more settings and impairing function.',CMDT),
  q(MENT,'A patient has repeated, unexpected episodes of pounding heart, shaking and fear of dying, and now worries constantly about the next attack. What is the diagnosis?','Panic disorder',['Social anxiety disorder','Agoraphobia only','Acute coronary syndrome'],'A','Panic disorder involves recurrent unexpected panic attacks followed by at least 1 month of worry about more attacks or changes in behavior.',CMDT),
  q(ASSESS,'A patient stands with feet together and eyes closed and begins to sway and lose balance. What does this positive test assess?','Romberg test of proprioception',['Rinne test of hearing','Babinski test of reflexes','Kernig test for meningitis'],'B','The Romberg test checks position sense; losing balance with eyes closed suggests a problem with proprioception (dorsal columns).',CMDT),
  q(ASSESS,'A patient with fever and headache flexes the hips and knees when the examiner bends the neck forward. What is this sign?','Brudzinski sign of meningeal irritation',['Murphy sign of gallbladder inflammation','Homans sign of a deep vein clot','Trousseau sign of low calcium levels'],'C','A positive Brudzinski sign, involuntary hip and knee flexion with neck flexion, suggests meningeal irritation such as meningitis.',CMDT),
  q(ASSESS,'While listening over the carotid artery, the examiner hears a whooshing sound. What does it suggest?','A bruit from turbulent flow through a narrowed artery',['A normal heart sound carried up from the chest','A friction rub from an inflamed pericardium','Wheezing carried up from the lower airways'],'D','A bruit is a whooshing sound from turbulent blood flow, often from atherosclerotic narrowing; a carotid bruit raises concern for stroke risk.',CMDT),
  q(ASSESS,'A patient has a blood pressure of 120/80 mm Hg. What is the mean arterial pressure?','About 93 mm Hg',['About 100 mm Hg','About 80 mm Hg','About 40 mm Hg'],'A','MAP = (systolic + 2 × diastolic) ÷ 3 = (120 + 160) ÷ 3 ≈ 93 mm Hg; a MAP of at least 65 is needed to perfuse organs.',CMDT),
  q(ASSESS,'A long-term smoker’s fingertips are bulbous, and the angle at the nail bed is lost. What does this finding usually suggest?','Chronic low oxygen or chronic lung disease',['A recent fungal infection of the nail bed','A vitamin C deficiency only','Normal aging of the fingers and nails'],'B','Digital clubbing is linked to chronic hypoxia and conditions such as lung cancer, bronchiectasis and cyanotic heart disease.',CMDT),
  q(ASSESS,'In a SOAP note, which item belongs in the Objective section?','Vital signs and physical exam findings',['The patient’s description of the pain','The clinician’s list of possible diagnoses','The plan for tests and follow-up visits'],'C','Objective data are measurable or observed findings such as vitals, exam and labs; the patient’s own report belongs in the Subjective section.',CMDT),
  q(DX,'A firm thyroid nodule is found on exam, and ultrasound shows suspicious features. What is the best next diagnostic step?','Fine-needle aspiration biopsy',['A repeat exam in five years','A chest X-ray only','A serum calcium level'],'D','Fine-needle aspiration samples cells from a suspicious thyroid nodule to check for cancer and guides the decision about surgery.',CMDT),
  q(DX,'For an average-risk adult, at what age does colorectal cancer screening generally begin under current USPSTF guidance?','45',['30','55','65'],'A','The USPSTF recommends colorectal cancer screening for average-risk adults starting at age 45, with options including colonoscopy and stool tests.',CMDT),
  q(DX,'A patient’s C-reactive protein is elevated. What does this tell the clinician?','Inflammation is present, but not its cause',['The patient has a bacterial infection','The patient has rheumatoid arthritis','The patient has had a heart attack'],'B','CRP and ESR are nonspecific markers of inflammation; they can rise in infection, autoimmune disease or injury and must be interpreted with other findings.',CMDT),
  q(DX,'Which test best measures the heart’s ejection fraction in a patient with suspected heart failure?','An echocardiogram',['A chest X-ray','A treadmill stress ECG','A fasting lipid panel'],'C','An echocardiogram uses ultrasound to show the heart’s chambers and valves and estimate ejection fraction, classifying heart failure type.',CMDT),
  q(DX,'A patient with suspected sepsis needs antibiotics. What should be done first, if it causes no significant delay?','Draw blood cultures',['Order a CT scan of the head','Wait for fever to resolve','Repeat the vital signs hourly'],'D','Blood cultures taken before antibiotics help identify the organism, but antibiotics should not be delayed more than briefly for them.',CMDT),
  q(DX,'An arterial blood gas shows pH 7.28, bicarbonate 16 mEq/L and PaCO2 30 mm Hg. What is the disorder?','Metabolic acidosis with respiratory compensation',['Respiratory acidosis with metabolic compensation','Metabolic alkalosis with respiratory compensation','Respiratory alkalosis with metabolic compensation'],'A','A low pH and low bicarbonate show metabolic acidosis; the low PaCO2 reflects faster breathing to blow off CO2 as compensation.',CMDT),
  q(DX,'Which screening test detects precancerous changes of the cervix?','A Pap test, with or without HPV testing',['A pelvic ultrasound of the ovaries','A CA-125 blood tumor marker test','A urine pregnancy test at each visit'],'B','The Pap test collects cervical cells to find dysplasia before cancer develops; HPV testing identifies the high-risk virus that causes most cases.',CMDT)
 ],8944)
};
